static inline /* <=== same_thread_group */ 
bool same_thread_group(struct task_struct *p1, struct task_struct *p2)
{
	return p1->signal == p2->signal;
}

int group_send_sig_info(int sig, struct siginfo *info, struct task_struct *p) /* <=== group_send_sig_info */ 
{
	int ret;

	rcu_read_lock();
	ret = check_kill_permission(sig, info, p);
	rcu_read_unlock();

	if (!ret && sig)
		ret = do_send_sig_info(sig, info, p, true);

	return ret;
}

static inline int pid_alive(const struct task_struct *p) /* <=== pid_alive */ 
{
	return p->pids[PIDTYPE_PID].pid != NULL;
}

static inline void rcu_read_unlock(void) /* <=== rcu_read_unlock */ 
{
	RCU_LOCKDEP_WARN(!rcu_is_watching(),
			 "rcu_read_unlock() used illegally while idle");
	__release(RCU);
	__rcu_read_unlock();
	rcu_lock_release(&rcu_lock_map); /* Keep acq info for rls diags. */
}

static int send_signal(int sig, struct siginfo *info, struct task_struct *t, /* <=== send_signal */ 
			int group)
{
	int from_ancestor_ns = 0;

#ifdef CONFIG_PID_NS
	from_ancestor_ns = si_fromuser(info) &&
			   !task_pid_nr_ns(current, task_active_pid_ns(t));
#endif

	return __send_signal(sig, info, t, group, from_ancestor_ns);
}

static inline void unlock_task_sighand(struct task_struct *tsk, /* <=== unlock_task_sighand */ 
						unsigned long *flags)
{
	spin_unlock_irqrestore(&tsk->sighand->siglock, *flags);
}

static inline struct pid *task_session(struct task_struct *task) /* <=== task_session */ 
{
	return task->group_leader->pids[PIDTYPE_SID].pid;
}

int security_task_kill(struct task_struct *p, struct siginfo *info, /* <=== security_task_kill */ 
			int sig, u32 secid)
{
	return call_int_hook(task_kill, 0, p, info, sig, secid);
}

static int check_kill_permission(int sig, struct siginfo *info, /* <=== check_kill_permission */ 
				 struct task_struct *t)
{
	struct pid *sid;
	int error;

	if (!valid_signal(sig))
		return -EINVAL;

	if (!si_fromuser(info))
		return 0;

	error = audit_signal_info(sig, t); /* Let audit system see the signal */
	if (error)
		return error;

	if (!same_thread_group(current, t) &&
	    !kill_ok_by_cred(t)) {
		switch (sig) {
		case SIGCONT:
			sid = task_session(t);
			/*
			 * We don't return the error if sid == NULL. The
			 * task was unhashed, the caller must notice this.
			 */
			if (!sid || sid == task_session(current))
				break;
		default:
			return -EPERM;
		}
	}

	return security_task_kill(t, info, sig, 0);
}

static inline struct pid *task_pid(struct task_struct *task) /* <=== task_pid */ 
{
	return task->pids[PIDTYPE_PID].pid;
}

struct pid *find_vpid(int nr) /* <=== find_vpid */ 
{
	return find_pid_ns(nr, task_active_pid_ns(current));
}

static int kill_ok_by_cred(struct task_struct *t) /* <=== kill_ok_by_cred */ 
{
	const struct cred *cred = current_cred();
	const struct cred *tcred = __task_cred(t);

	if (uid_eq(cred->euid, tcred->suid) ||
	    uid_eq(cred->euid, tcred->uid)  ||
	    uid_eq(cred->uid,  tcred->suid) ||
	    uid_eq(cred->uid,  tcred->uid))
		return 1;

	if (ns_capable(tcred->user_ns, CAP_KILL))
		return 1;

	return 0;
}

static inline struct pid *task_pgrp(struct task_struct *task) /* <=== task_pgrp */ 
{
	return task->group_leader->pids[PIDTYPE_PGID].pid;
}

static inline int security_task_kill(struct task_struct *p, /* <=== security_task_kill */ 
				     struct siginfo *info, int sig,
				     u32 secid)
{
	return 0;
}

static inline int valid_signal(unsigned long sig) /* <=== valid_signal */ 
{
	return sig <= _NSIG ? 1 : 0;
}

static inline pid_t task_pid_vnr(struct task_struct *tsk) /* <=== task_pid_vnr */ 
{
	return __task_pid_nr_ns(tsk, PIDTYPE_PID, NULL);
}

static inline bool si_fromuser(const struct siginfo *info) /* <=== si_fromuser */ 
{
	return info == SEND_SIG_NOINFO ||
		(!is_si_special(info) && SI_FROMUSER(info));
}

static inline struct pid_namespace *ns_of_pid(struct pid *pid) /* <=== ns_of_pid */ 
{
	struct pid_namespace *ns = NULL;
	if (pid)
		ns = pid->numbers[pid->level].ns;
	return ns;
}

pid_t pid_nr_ns(struct pid *pid, struct pid_namespace *ns) /* <=== pid_nr_ns */ 
{
	struct upid *upid;
	pid_t nr = 0;

	if (pid && ns->level <= pid->level) {
		upid = &pid->numbers[ns->level];
		if (upid->ns == ns)
			nr = upid->nr;
	}
	return nr;
}

struct pid *find_pid_ns(int nr, struct pid_namespace *ns) /* <=== find_pid_ns */ 
{
	struct upid *pnr;

	hlist_for_each_entry_rcu(pnr,
			&pid_hash[pid_hashfn(nr, ns)], pid_chain)
		if (pnr->nr == nr && pnr->ns == ns)
			return container_of(pnr, struct pid,
					numbers[ns->level]);

	return NULL;
}

pid_t __task_pid_nr_ns(struct task_struct *task, enum pid_type type, /* <=== __task_pid_nr_ns */ 
			struct pid_namespace *ns)
{
	pid_t nr = 0;

	rcu_read_lock();
	if (!ns)
		ns = task_active_pid_ns(current);
	if (likely(pid_alive(task))) {
		if (type != PIDTYPE_PID)
			task = task->group_leader;
		nr = pid_nr_ns(rcu_dereference(task->pids[type].pid), ns);
	}
	rcu_read_unlock();

	return nr;
}

int do_send_sig_info(int sig, struct siginfo *info, struct task_struct *p, /* <=== do_send_sig_info */ 
			bool group)
{
	unsigned long flags;
	int ret = -ESRCH;

	if (lock_task_sighand(p, &flags)) {
		ret = send_signal(sig, info, p, group);
		unlock_task_sighand(p, &flags);
	}

	return ret;
}

static inline void rcu_read_lock(void) /* <=== rcu_read_lock */ 
{
	__rcu_read_lock();
	__acquire(RCU);
	rcu_lock_acquire(&rcu_lock_map);
	RCU_LOCKDEP_WARN(!rcu_is_watching(),
			 "rcu_read_lock() used illegally while idle");
}

struct pid_namespace *task_active_pid_ns(struct task_struct *tsk) /* <=== task_active_pid_ns */ 
{
	return ns_of_pid(task_pid(tsk));
}

int __kill_pgrp_info(int sig, struct siginfo *info, struct pid *pgrp) /* <=== __kill_pgrp_info */ 
{
	struct task_struct *p = NULL;
	int retval, success;

	success = 0;
	retval = -ESRCH;
	do_each_pid_task(pgrp, PIDTYPE_PGID, p) {
		int err = group_send_sig_info(sig, info, p);
		success |= !err;
		retval = err;
	} while_each_pid_task(pgrp, PIDTYPE_PGID, p);
	return success ? 0 : retval;
}

static inline struct sighand_struct *lock_task_sighand(struct task_struct *tsk, /* <=== lock_task_sighand */ 
						       unsigned long *flags)
{
	struct sighand_struct *ret;

	ret = __lock_task_sighand(tsk, flags);
	(void)__cond_lock(&tsk->sighand->siglock, ret);
	return ret;
}

